import{_ as t,o as a,c as i,a0 as s}from"./chunks/framework.BGyYNsHo.js";const p=JSON.parse('{"title":"Dynamic Preissmann slot","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/engine-modifications/04-dynamic-preissmann-slot.md","filePath":"explanation/engine-modifications/04-dynamic-preissmann-slot.md"}'),n={name:"explanation/engine-modifications/04-dynamic-preissmann-slot.md"};function r(o,e,h,l,c,d){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="dynamic-preissmann-slot" tabindex="-1">Dynamic Preissmann slot <a class="header-anchor" href="#dynamic-preissmann-slot" aria-label="Permalink to &quot;Dynamic Preissmann slot&quot;">​</a></h1><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>The <code>SURCHARGE_METHOD DYNAMIC_SLOT</code> option adds a third method of surcharged flow. Official SWMM offers two ways of representing pressurized flow in closed conduits: the EXTRAN algorithm (Hardy–Cross-type perturbation with $dQ/dH$) and the static Preissmann slot. Both have known limitations in filling/emptying transients: the static slot fixes its width from the instantaneous depth, which at the free-surface/pressure mixing front produces &quot;slot squeezing&quot;, an artificial energy amplification. The <code>DYNAMIC_SLOT</code> extension implements the <em>dynamic</em> Preissmann slot formulation of Sharior, Hodges &amp; Vasconcelos (2023), in which the slot area evolves in time as a <em>transient storage</em> element.</p><h2 id="formulation" tabindex="-1">Formulation <a class="header-anchor" href="#formulation" aria-label="Permalink to &quot;Formulation&quot;">​</a></h2><p>The dynamic slot has an upper width that depends on the Preissmann number $P$ and on a target pressure wave celerity $c_{pT}$ (set by the user with <code>DPS_CELERITY</code>, 25 m/s by default):</p><p>$$T_s = \\frac{g,A_{\\mathrm{full}}}{c_{pT}^{2}},P^{2},$$</p><p>where $A_{\\mathrm{full}}$ is the full-section area. The Preissmann number starts, at the beginning of pressurization, at</p><p>$$P_{0} = \\max!\\left(\\frac{c_{pT}}{\\alpha,c_g},\\ 1\\right), \\qquad c_g = \\sqrt{g,A_{\\mathrm{full}}/W_{\\max}},$$</p><p>with $\\alpha$ the shock parameter (<code>DPS_ALPHA</code>, 3 by default) and $c_g$ the gravity wave celerity at full section. The slot area is accumulated in a <em>path-dependent</em> way:</p><p>$$A_s \\leftarrow \\max!\\left(A_s + T_s,\\Delta h_s,\\ 0\\right), \\qquad h_s = \\max(\\bar y - y_{\\mathrm{full}},\\ 0),$$</p><p>that is, each storage increment is created with the slot width in force at the moment it is accumulated, and previous contributions are never rewritten when $P$ decays. This property is what avoids the energy amplification of &quot;slot squeezing&quot;. If the head falls below the crown with residual area, the overpressure head is kept at zero and the remaining area drains through successive negative increments (depressurization hysteresis).</p><p>After pressurization, $P$ decays exponentially toward 1 with the time scale <code>DPS_DECAY_TIME</code> ($r = 0.5$ s by default):</p><p>$$\\hat P(t) = 1 + (\\hat P_0 - 1)\\exp!\\left(-\\frac{10,(t - t_s)}{r}\\right),$$</p><p>with $t_s$ the instant the conduit entered surcharge, and it is smoothed spatially once per step by averaging $\\hat P$ over the conduits incident to each node and taking as the working $P$ the average of the two ends of the conduit.</p><h2 id="consequences-for-the-solver" tabindex="-1">Consequences for the solver <a class="header-anchor" href="#consequences-for-the-solver" aria-label="Permalink to &quot;Consequences for the solver&quot;">​</a></h2><p>While a slot is active:</p><ul><li>the hydraulic area is $A = A_{\\mathrm{full}} + A_s$ and the top width is $T_s$;</li><li>the surface area contributed to a surcharged end node is $T_s,L/4$;</li><li>the hydraulic radius stays at its full-section value (the slot contributes storage but no friction);</li><li>node heads are <em>always</em> updated with the ordinary free-surface formula; the EXTRAN surcharge branch is never invoked, and the piezometric head above the crown emerges naturally as $z_{\\mathrm{inv}} + y_{\\mathrm{full}} + h_s$.</li></ul><p>The variable time step uses the effective pressure celerity $c_p = c_{pT}/P$ in the Courant condition of the surcharged conduit:</p><p>$$\\Delta t \\le \\frac{L}{\\lvert \\bar U \\rvert + c_{pT}/P}.$$</p>',19)])])}const u=t(n,[["render",r]]);export{p as __pageData,u as default};
